225	    /**
226	     * Determines whether an owner conflicting with the given one already exists, i.e. any existing
227	     * owner using the same telephone number.
228	     *
229	     * @param owner the candidate owner to check
230	     * @return {@code true} if another owner already uses the telephone number, {@code false} otherwise
231	     */
232	    /**
233	     * Builds the customer code assigned to a newly created owner, formatted as
234	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
235	     * already registered in the same city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
236	     *
237	     * @param owner the owner being created
238	     * @return the customer code for the owner
239	     */
240	    private String customerCode(Owner owner) {
241	        String city = owner.getCity();
242	        long existingInCity = this.clinicService.findAllOwners().stream()
243	            .filter(existing -> Objects.equals(existing.getCity(), city))
244	            .count();
245	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), existingInCity + 1);
246	    }
247	
248	    /**
249	     * Determines the canonical spelling of the city for a newly created owner. If another owner
250	     * already lives in the same city (matched case- and whitespace-insensitively), that owner's exact
251	     * spelling of the city name is reused so that all owners in a city share a consistent value.
252	     * Otherwise the supplied city is title-cased (e.g. {@code "new york"} becomes {@code "New York"}).
253	     *
254	     * @param city the raw city as supplied when creating the owner, may be {@code null}
255	     * @return the canonical city spelling, or {@code null} if {@code city} was {@code null}
256	     */
257	    private String canonicalCity(String city) {
258	        if (city == null) {
259	            return null;
260	        }
261	        String normalized = normalize(city);
262	        for (Owner existing : this.clinicService.findAllOwners()) {
263	            if (existing.getCity() != null && normalized.equals(normalize(existing.getCity()))) {
264	                return existing.getCity();
265	            }
266	        }
267	        return titleCase(city);
268	    }
269	
270	    /**
271	     * Title-cases a value by upper-casing the first letter of every whitespace-separated word and
272	     * lower-casing the rest, collapsing any run of internal whitespace to a single space (e.g.
273	     * {@code "new  YORK city"} becomes {@code "New York City"}).
274	     *
275	     * @param value the value to title-case
276	     * @return the title-cased value
277	     */
278	    private static String titleCase(String value) {
279	        StringBuilder result = new StringBuilder();
280	        for (String word : value.strip().split("\\s+")) {
281	            if (word.isEmpty()) {
282	                continue;
283	            }
284	            if (result.length() > 0) {
285	                result.append(' ');
286	            }
287	            result.append(Character.toUpperCase(word.charAt(0)))
288	                .append(word.substring(1).toLowerCase(Locale.ROOT));
289	        }
290	        return result.toString();
291	    }
292	
293	    /**
294	     * Determines whether the maximum number of owners allowed to be registered on a single day has
295	     * already been reached. At most 20 owners may be created with today's registration date; once
296	     * that many exist, further registrations for today are rejected.
297	     *
298	     * @return {@code true} if 20 or more owners already have today's registration date
299	     */
300	    private boolean isDailyRegistrationLimitReached() {
301	        LocalDate today = LocalDate.now();
302	        long registeredToday = this.clinicService.findAllOwners().stream()
303	            .filter(existing -> today.equals(existing.getRegistrationDate()))
304	            .count();
305	        return registeredToday >= 20;
306	    }
307	
308	    /**
309	     * Determines whether the city of a newly created owner has already reached its capacity. At most
310	     * 8 owners may live in a single city; once a city already contains 8 owners, further registrations
311	     * for that city are rejected. Cities are matched case- and whitespace-insensitively so that
312	     * differing spellings of the same city name count towards the same limit.
313	     *
314	     * @param city the canonical city of the owner being created, may be {@code null}
315	     * @return {@code true} if the city already contains 8 or more owners, {@code false} otherwise
316	     */
317	    private boolean isCityCapacityReached(String city) {
318	        String normalized = normalize(city);
319	        long existingInCity = this.clinicService.findAllOwners().stream()
320	            .filter(existing -> Objects.equals(normalized, normalize(existing.getCity())))
321	            .count();
322	        return existingInCity >= 8;
323	    }
324	
325	    private boolean isDuplicateOwner(Owner owner) {
326	        return this.clinicService.findAllOwners().stream()
327	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
328	    }
329	
330	    /**
331	     * Normalises a telephone number to digits only by stripping spaces, dashes and parentheses (and
332	     * any other non-digit characters). This is applied before storing the number and before the
333	     * telephone-uniqueness check, so that e.g. {@code "(613) 555-0100"} and {@code "6135550100"} are
334	     * stored identically and treated as the same number.
335	     *
336	     * @param telephone the raw telephone number, may be {@code null}
337	     * @return the digits-only telephone number, or {@code null} if {@code telephone} was {@code null}
338	     */
339	    private static String normalizeTelephone(String telephone) {
340	        if (telephone == null) {
341	            return null;
342	        }
343	        return telephone.replaceAll("[^0-9]", "");
344	    }
345	
346	    /**
347	     * Determines whether the given owner's email address is already used by another owner. An owner
348	     * without an email address never conflicts. The comparison is case-insensitive and ignores
349	     * surrounding or repeated whitespace, so e.g. {@code "  John.Smith@Example.com "} and
350	     * {@code "john.smith@example.com"} are treated as the same address.
351	     *
352	     * @param owner the candidate owner to check
353	     * @return {@code true} if another owner already uses the email address, {@code false} otherwise
354	     */
355	    private boolean isDuplicateEmail(Owner owner) {
356	        String email = normalize(owner.getEmail());
357	        if (email == null || email.isEmpty()) {
358	            return false;
359	        }
360	        return this.clinicService.findAllOwners().stream()
361	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
362	    }
363	
364	    /**
365	     * Normalises a value for case- and whitespace-insensitive duplicate detection: surrounding
366	     * whitespace is stripped, any run of internal whitespace is collapsed to a single space and all
367	     * letters are lower-cased. This is what makes {@code "  john   smith "} and {@code "John Smith"}
368	     * count as the same person (or, for e-mail, the same address) when detecting duplicates.
369	     *
370	     * @param value the raw value, may be {@code null}
371	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
372	     */
373	    private static String normalize(String value) {
374	        if (value == null) {
375	            return null;
376	        }
377	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
378	    }
379	}
